import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.BZohXCq9.js";const h=JSON.parse('{"title":"相机与 IMU 差 4ms：先查时间戳语义，不要先怪 MCU","description":"用 sample time、camera PTS、trigger time 与 VINS td 拆解固定时间偏差","frontmatter":{"title":"相机与 IMU 差 4ms：先查时间戳语义，不要先怪 MCU","description":"用 sample time、camera PTS、trigger time 与 VINS td 拆解固定时间偏差","tags":["Camera","IMU","Timestamp","VINS","PX4"],"date":"2026/07/03"},"headers":[],"relativePath":"uav/camera-imu-timestamp-semantics.md","filePath":"uav/camera-imu-timestamp-semantics.md","lastUpdated":1784519165000}'),l={name:"uav/camera-imu-timestamp-semantics.md"};function p(n,e,r,c,d,o){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="相机与-imu-差-4ms-先查时间戳语义-不要先怪-mcu" tabindex="-1">相机与 IMU 差 4ms：先查时间戳语义，不要先怪 MCU <a class="header-anchor" href="#相机与-imu-差-4ms-先查时间戳语义-不要先怪-mcu" aria-label="Permalink to &quot;相机与 IMU 差 4ms：先查时间戳语义，不要先怪 MCU&quot;">​</a></h1><p>在相机-IMU 标定或 VIO 日志中看到固定几毫秒偏差，很容易把问题归到 PX4 或串口同步。更常见的情况是：两条链路记录的根本不是同一个物理时刻。</p><h2 id="先画出时间语义" tabindex="-1">先画出时间语义 <a class="header-anchor" href="#先画出时间语义" aria-label="Permalink to &quot;先画出时间语义&quot;">​</a></h2><p>IMU 常见时间点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>真实采样 → sensor sample timestamp → PX4 timestamp_sample</span></span>\n<span class="line"><span>        → timesync 映射 → ROS header.stamp → callback receipt</span></span></code></pre></div><p>相机常见时间点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>trigger → 曝光开始/中心/结束 → sensor/driver PTS</span></span>\n<span class="line"><span>       → userspace timestamp → ROS header.stamp → callback receipt</span></span></code></pre></div><p>如果 IMU 使用 sample time，而相机使用帧完成或 dequeue 时间，两者稳定相差几毫秒并不奇怪。</p><h2 id="第一步-判断是不是整帧错位" tabindex="-1">第一步：判断是不是整帧错位 <a class="header-anchor" href="#第一步-判断是不是整帧错位" aria-label="Permalink to &quot;第一步：判断是不是整帧错位&quot;">​</a></h2><p>先用频率做 sanity check。假设相机触发为 20 Hz：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一帧周期 = 1 / 20 s = 50 ms</span></span></code></pre></div><p>如果 sequence 真错了一帧，误差量级更接近 50 ms。观测只有 4 ms 或 9 ms，通常更像曝光/PTS 定义、驱动延迟或消费者内部时间修正，而不是整帧 sequence slip。</p><h2 id="第二步-确认同步链本身是否稳定" tabindex="-1">第二步：确认同步链本身是否稳定 <a class="header-anchor" href="#第二步-确认同步链本身是否稳定" aria-label="Permalink to &quot;第二步：确认同步链本身是否稳定&quot;">​</a></h2><p>查看：</p><ul><li><code>has_sync</code> 是否持续成立；</li><li>raw offset 与 filtered offset 的抖动；</li><li>IMU 消息率是否稳定；</li><li>PPS / trigger sequence 是否连续；</li><li>串口是否存在第二个 reader 抢数据。</li></ul><p>如果同步 offset 的 jitter 只有数百微秒，而偏差稳定在数毫秒，继续调同步滤波通常不会解决根因。</p><h2 id="第三步-追相机-pts-的定义" tabindex="-1">第三步：追相机 PTS 的定义 <a class="header-anchor" href="#第三步-追相机-pts-的定义" aria-label="Permalink to &quot;第三步：追相机 PTS 的定义&quot;">​</a></h2><p>需要确认驱动给出的 PTS 对应：</p><ul><li>外部 trigger 到达；</li><li>曝光开始；</li><li>曝光中心；</li><li>曝光结束；</li><li>ISP 完成；</li><li>buffer dequeue。</li></ul><p>对 VIO 来说，通常希望使用与成像物理时刻相关的 timestamp，而不是用户态收到 buffer 的时间。若使用外部 <code>CAMERA_TRIGGER</code>，还要把 trigger sequence 与 frame sequence 持续绑定，不能只在启动时对齐一次。</p><h2 id="第四步-检查-vins-是否又估了一次-td" tabindex="-1">第四步：检查 VINS 是否又估了一次 <code>td</code> <a class="header-anchor" href="#第四步-检查-vins-是否又估了一次-td" aria-label="Permalink to &quot;第四步：检查 VINS 是否又估了一次 `td`&quot;">​</a></h2><p>即使 ROS camera stamp 已经直接使用 trigger time，VINS 配置仍可能启用 <code>estimate_td</code> 并维护非零 <code>td</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>image_time_used_by_vins = image_stamp + td</span></span></code></pre></div><p>此时标定或优化结果看到的 residual，不再只反映消息 stamp 链路。排查时要同时查看运行时配置和日志，明确 <code>td</code> 是固定为 0、固定标定值，还是在线估计。</p><h2 id="推荐排查顺序" tabindex="-1">推荐排查顺序 <a class="header-anchor" href="#推荐排查顺序" aria-label="Permalink to &quot;推荐排查顺序&quot;">​</a></h2><ol><li>用帧周期判断是否可能是 sequence slip；</li><li>验证 PPS/MAVLink offset 的稳定性；</li><li>对照 IMU sample time 与相机 PTS 的物理定义；</li><li>检查 trigger seq 到 frame seq 的对应；</li><li>检查 VINS <code>td/estimate_td</code>；</li><li>最后再讨论 MCU timestamp 生成逻辑。</li></ol><p>这类问题的关键不是把所有 timestamp 都变成同一个数，而是让每个时间戳都明确回答：<strong>它代表哪个物理事件，属于哪个时钟域，经过了哪些转换。</strong></p>',27)])])}const u=a(l,[["render",p]]);export{h as __pageData,u as default};
